using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.Build.Reporting;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
// Narrow A/B using the unchanged production shader and 2 original +X triangles.
public static class GoldSideMaterialChecks{
 static string Arg(string key){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,key)+1];}
 [Serializable]class Result{public bool pass;public string error,folder,packedFormat,rawPackedFormat;public int rawMips,triangles;public ulong bytes;public int warnings,errors;}
 public static void Run(){var output=Arg("-side-output");Directory.CreateDirectory(output);var report=new Result();var old=GraphicsSettings.defaultRenderPipeline;var oldQ=QualitySettings.renderPipeline;int code=0;try{
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string folder=AssetDatabase.GenerateUniqueAssetPath("Assets/GoldSideMaterialProof");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));report.folder=folder;var rd=ScriptableObject.CreateInstance<UniversalRendererData>();AssetDatabase.CreateAsset(rd,folder+"/Renderer.asset");var rp=UniversalRenderPipelineAsset.Create(rd);AssetDatabase.CreateAsset(rp,folder+"/Pipeline.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Isolated side sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.None;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));RenderSettings.sun=sun;
 var data=SmallPropsV1.Read(Path.Combine(Arg("-props-export"),"small_props.json"));var built=MapSharedPropsBuilder.Build(Arg("-props-export"));var prefab=built.prefabs["treasurechest_gold"];var source=prefab.GetComponent<MeshFilter>().sharedMesh;var vertices=source.vertices;var normals=source.normals;var indices=source.triangles;var selected=new List<int>();for(int k=0;k<indices.Length;k+=3){var tri=indices.Skip(k).Take(3).ToArray();if(tri.All(i=>Mathf.Abs(vertices[i].x-.5125f)<.00002f&&normals[i].x>.95f))selected.AddRange(tri);}if(selected.Count!=6)throw new Exception("Expected exactly two original side triangles, got "+selected.Count);var mesh=UnityEngine.Object.Instantiate(source);mesh.triangles=selected.ToArray();mesh.bounds=new Bounds(new Vector3(.5125f,.2125f,0),new Vector3(.001f,.425f,.618f));AssetDatabase.CreateAsset(mesh,folder+"/OriginalSide.asset");var face=new GameObject("Actual gold positive-X side");face.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=face.AddComponent<MeshRenderer>();renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;var material=new Material(prefab.GetComponent<Renderer>().sharedMaterial);material.SetFloat("_ChestTime",0);AssetDatabase.CreateAsset(material,folder+"/Production.mat");report.packedFormat=((Texture2D)material.GetTexture("_ChestPacked")).format.ToString();UnityEngine.Object.DestroyImmediate(built.root);
 string text=File.ReadAllText("Assets/MapSharedProps/Runtime/ChestMetal.shader");string hook="detail=ChestPacked(surfaceUV,i.surface,i.positionOS);";if(!text.Contains(hook))throw new Exception("Missing production NR hook");text=text.Replace("Shader \"MapSharedProps/ChestMetal\"","Shader \"Hidden/GoldSideMaterialProof\"").Replace("_BaseMap(\"Base colour\"","_ProbeNormal(\"Diagnostic normal\",Float)=1 _ProbeRough(\"Diagnostic roughness\",Float)=1 _ProbeData(\"Diagnostic data\",Float)=0 _BaseMap(\"Base colour\"").Replace("_Cutoff,_Cull,_ChestVariant;","_Cutoff,_Cull,_ChestVariant,_ProbeNormal,_ProbeRough,_ProbeData;").Replace("#include \"ChestSurface.hlsl\"","#include \"Assets/MapSharedProps/Runtime/ChestSurface.hlsl\"").Replace(hook,hook+"detail.xy=lerp(detail.xy,.5,ChestPattern(i.positionOS)*(1-_ProbeNormal));detail.b=lerp(detail.b,_ChestMean3.a,ChestPattern(i.positionOS)*(1-_ProbeRough));").Replace("float3 nv=normalize", "\n#if defined(CHEST_SURFACE)\nif(_ProbeData>.5)return _ProbeData<1.5?half4(detail.rgb,1):half4(ChestPattern(i.positionOS),ChestFade(surfaceUV,i.surface),0,1);\n#endif\nfloat3 nv=normalize");string file=folder+"/Probe.shader";File.WriteAllText(file,text);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);var shader=AssetDatabase.LoadAssetAtPath<Shader>(file);if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Diagnostic production clone failed shader compile");
 var raw=new Texture2D(512,512,TextureFormat.RGBA32,true,true);raw.LoadImage(Convert.FromBase64String(data.chestSurfacesV1.packed.png));raw.wrapMode=TextureWrapMode.Clamp;raw.filterMode=FilterMode.Trilinear;raw.anisoLevel=2;raw.Apply(true,false);AssetDatabase.CreateAsset(raw,folder+"/UncompressedPacked.asset");report.rawPackedFormat=raw.format.ToString();report.rawMips=raw.mipmapCount;
 var names=new[]{"production","full","no-normal","no-roughness","flat-both","uncompressed","packed-bc7","packed-raw","weights"};var mats=new List<Material>{material};foreach(string name in names.Skip(1)){var m=new Material(material);m.shader=shader;m.EnableKeyword("CHEST_SURFACE");m.SetFloat("_ProbeNormal",name=="no-normal"||name=="flat-both"?0:1);m.SetFloat("_ProbeRough",name=="no-roughness"||name=="flat-both"?0:1);m.SetFloat("_ProbeData",name.StartsWith("packed")?1:name=="weights"?2:0);if(name=="uncompressed"||name=="packed-raw")m.SetTexture("_ChestPacked",raw);AssetDatabase.CreateAsset(m,folder+"/"+name+".mat");mats.Add(m);}var camera=new GameObject("Side camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.fieldOfView=35;camera.nearClipPlane=.01f;camera.farClipPlane=10;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.055f,.065f,.08f);var controller=new GameObject("Gold side material probe").AddComponent<GoldSideMaterialProbe>();controller.face=renderer;controller.proofCamera=camera;controller.materials=mats.ToArray();controller.modes=names;controller.CaptureAll(Path.Combine(output,"editor"));EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),folder+"/Side.unity");AssetDatabase.SaveAssets();var build=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{folder+"/Side.unity"},locationPathName=Path.Combine(output,"GoldSideProbe.exe"),target=BuildTarget.StandaloneWindows64,subtarget=(int)StandaloneBuildSubtarget.Player,options=BuildOptions.Development});report.bytes=build.summary.totalSize;report.warnings=build.summary.totalWarnings;report.errors=build.summary.totalErrors;report.triangles=2;report.pass=build.summary.result==BuildResult.Succeeded&&report.errors==0;if(!report.pass)code=1;
 }catch(Exception e){report.error=e.ToString();Debug.LogException(e);code=1;}finally{GraphicsSettings.defaultRenderPipeline=old;QualitySettings.renderPipeline=oldQ;AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(output,"build-report.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}}
}
